const input = $input.first().json;

const height  = parseFloat(input.height)  || null;  // cm
const weight  = parseFloat(input.weight)  || null;  // kg
const bust    = parseFloat(input.bust)    || null;  // cm, tùy chọn
const waist   = parseFloat(input.waist)   || null;  // cm, tùy chọn
const hip     = parseFloat(input.hip)     || null;  // cm, tùy chọn
const category = (input.category || 'top').toLowerCase();  // top | bottom | dress
const gender   = (input.gender   || 'nu').toLowerCase();   // nu | nam
const fabric   = (input.fabric   || 'normal').toLowerCase(); // normal | stretch | denim | oversize

if (!height && !weight && !bust && !waist && !hip) {
  return [{
    json: {
      status: 'need_more_info',
      message: 'Bạn ơi, để tư vấn size chính xác shop cần biết thêm chiều cao và cân nặng của bạn nhé! Bạn cho mình xin thông tin đó được không? 😊',
      missing: ['height', 'weight']
    }
  }];
}

return [{
  json: {
    status: 'ok',
    height, weight, bust, waist, hip,
    category, gender, fabric
  }
}];

const sheetData = $input.all();

const customerData = $('Extract Size Inputs').first().json;

if (customerData.status === 'need_more_info') {
  return [{ json: customerData }];
}

const { height, weight, category, gender, fabric } = customerData;

function matchCategory(phanLoai, category, gender) {
  const pl = phanLoai.toLowerCase();
  const cat = (category || '').toLowerCase();
  const gen = (gender || 'nu').toLowerCase();

  if (cat === 'giay') {
    if (gen === 'nam') return pl.includes('giày nam');
    return pl.includes('giày nữ');
  }
  if (cat === 'do lot') {
    if (gen === 'nam') return pl.includes('đồ lót nam');
    return pl.includes('đồ lót nữ');
  }

  const fabricMap = {
    slimfit: 'slimfit',
    regular: 'regular fit',
    oversized: 'oversized',
    oversize: 'oversized'
  };
  const fabricKey = fabricMap[fabric] || 'regular fit';
  return pl.includes(cat) && pl.includes(fabricKey);
}


const filtered = sheetData.filter(item => {
  const phanLoai = item.json['Phân loại'] || '';
  return matchCategory(phanLoai, category, gender);
});

if (filtered.length === 0) {
  return [{ json: {
    status: 'no_match',
    message: `Shop chưa có dữ liệu size cho sản phẩm này, bạn nhắn tin trực tiếp để được tư vấn nhé! 😊`
  }}];
}


function scoreRow(row, h, w) {
  const hMin = parseFloat(row['Chiều cao Min (cm)']) || 0;
  const hMax = parseFloat(row['Chiều cao Max (cm)']) || 999;
  const wMin = parseFloat(row['Cân nặng Min (kg)']) || 0;
  const wMax = parseFloat(row['Cân nặng Max (kg)']) || 999;

  let score = 0;

  if (h !== null) {
    if (h >= hMin && h <= hMax) score += 2;
    else if (h > hMax) score -= 2;
    else score -= 1;
  }
  if (w !== null) {
    if (w >= wMin && w <= wMax) score += 2;
    else if (w > wMax) score -= 2;
    else score -= 1;
  }
  return score;
}

const scored = filtered.map(item => ({
  size: item.json['Size'],
  score: scoreRow(item.json, height, weight),
  ghiChu: item.json['Ghi chú tư vấn'] || ''
})).sort((a, b) => b.score - a.score);

const best = scored[0];
const runnerUp = scored[1];

const confidence = best.score >= 3 ? 'cao'
                 : best.score >= 1 ? 'trung bình'
                 : 'thấp';

return [{ json: {
  status: 'success',
  recommendedSize: best.size,
  originalBestSize: best.size,
  runnerUpSize: runnerUp?.size || null,
  confidence,
  fabricNote: '',
  measureInfo: [height && `chiều cao ${height}cm`, weight && `cân nặng ${weight}kg`].filter(Boolean).join(', '),
  catLabel: category,
  gender,
  ghiChu: best.ghiChu,
  scores: scored.map(s => ({ size: s.size, score: s.score }))
}}];

const d = $input.first().json;

if (d.status === 'need_more_info') {
  return [{ json: { reply: d.message, status: 'need_more_info' } }];
}

const { recommendedSize, originalBestSize, runnerUpSize, confidence,
        fabricNote, measureInfo, catLabel, gender, scores } = d;

const genderWord = gender === 'nam' ? 'bạn nam' : 'bạn';

let reply = '';

if (confidence === 'cao') {
  reply = `Dựa trên thông số ${measureInfo}, shop tư vấn ${genderWord} mặc **size ${recommendedSize}**${fabricNote} cho ${catLabel} này nhé! 🎉`;
} else if (confidence === 'trung bình') {
  reply = `Dựa trên ${measureInfo}, shop gợi ý **size ${recommendedSize}** cho ${catLabel}.${fabricNote} Tuy nhiên vì số đo nằm gần ranh giới, ${genderWord} có thể cân nhắc thêm **size ${runnerUpSize || recommendedSize}** nếu thích mặc rộng hơn một chút nhé.`;
} else {
  reply = `Thông số ${measureInfo} hơi đặc biệt nên shop khó tư vấn chắc chắn. Shop tạm gợi ý **size ${recommendedSize}**, nhưng ${genderWord} cho mình xin thêm số đo vòng ngực/eo/hông để tư vấn chính xác hơn được không? 😊`;
}

if (recommendedSize !== originalBestSize) {
  reply += `\n\n💡 *Lưu ý: Theo bảng size thông thường là ${originalBestSize}, nhưng do ${fabricNote.replace(' (', '').replace(')', '')}, shop đề xuất điều chỉnh xuống ${recommendedSize}.*`;
}

return [{
  json: {
    status: 'success',
    reply,
    recommendedSize,
    confidence,
    scores
  }
}];
